const cfg = $('Config').first().json;
const out = [];
for (const wo of cfg.deLocations) {
  for (const was of cfg.keywords) {
    out.push({ json: { was, wo, umkreis: cfg.deRadiusKm, size: cfg.perQuery, days: cfg.maxDaysOld } });
  }
}
return out;

const out = [];
for (const item of $input.all()) {
  for (const j of (item.json.ergebnisliste || [])) {
    const adr = ((j.stellenlokationen || [])[0] || {}).adresse || {};
    const ref = j.referenznummer || '';
    out.push({ json: {
      source: 'bundesagentur',
      ref,
      title: j.stellenangebotsTitel || '',
      company: j.firma || j.allianzpartnerName || 'Unbekannt',
      city: adr.ort || '',
      region: adr.region || '',
      country: 'DE',
      postedAt: j.datumErsteVeroeffentlichung || (j.veroeffentlichungszeitraum || {}).von || '',
      homeoffice: !!j.homeofficemoeglich,
      isAgency: !!(j.istPrivateArbeitsvermittlung || j.istArbeitnehmerUeberlassung),
      url: ref ? 'https://www.arbeitsagentur.de/jobsuche/jobdetail/' + encodeURIComponent(ref) : '',
      description: '',
      contactEmail: ''
    }});
  }
}
return out;

const cfg = $('Config').first().json;
// No Adzuna key -> skip the Amsterdam branch entirely instead of erroring.
if (!cfg.adzunaAppId || !cfg.adzunaAppKey) return [];
return cfg.keywords.map(what => ({
  json: { what, where: cfg.nlLocation, distance: cfg.nlRadiusKm, days: cfg.maxDaysOld, size: cfg.perQuery }
}));

const out = [];
for (const item of $input.all()) {
  for (const j of (item.json.results || [])) {
    out.push({ json: {
      source: 'adzuna',
      ref: String(j.id || ''),
      title: j.title || '',
      company: (j.company || {}).display_name || 'Unknown',
      city: (j.location || {}).display_name || 'Amsterdam',
      region: 'Noord-Holland',
      country: 'NL',
      postedAt: (j.created || '').slice(0, 10),
      homeoffice: /remote|hybrid|thuiswerk/i.test(j.description || ''),
      isAgency: /recruit|staffing|uitzend|detacher/i.test((j.company || {}).display_name || ''),
      url: j.redirect_url || '',
      description: (j.description || '').replace(/<[^>]+>/g, ' '),
      contactEmail: ''   // Adzuna never exposes one -> these always land in the review queue
    }});
  }
}
return out;

const cfg = $('Config').first().json;
const pos = (cfg.titleMustMatch || []).map(s => String(s).toLowerCase());
const neg = (cfg.titleExclude || []).map(s => String(s).toLowerCase());
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const t = ' ' + String(j.title || '').toLowerCase() + ' ';
  if (!pos.some(p => t.includes(p))) continue;
  if (neg.some(n => t.includes(n))) continue;
  if (cfg.excludeAgencies && j.isAgency) continue;
  if (!j.title || !j.company) continue;
  // Chiffre / anonymous ads have no addressable employer - a cover letter to "Unbekannt" is wasted.
  if (/^(unbekannt|unknown|vertraulich|confidential)$/i.test(String(j.company).trim())) continue;
  out.push({ json: j });
}
return out;

const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};

// forget old entries so a re-posted role can resurface after a while
const now = Date.now();
const ttl = (cfg.rememberDays || 120) * 86400000;
for (const k of Object.keys(sd.seen)) { if (now - sd.seen[k] > ttl) delete sd.seen[k]; }

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const seenThisRun = new Set();
const companiesThisRun = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const co = norm(j.company);
  const key = co + '|' + norm(j.title);
  if (sd.seen[key] || seenThisRun.has(key)) continue;
  // At most one approach per company per run - two mails the same morning reads as a bot.
  if (companiesThisRun.has(co)) continue;
  seenThisRun.add(key);
  companiesThisRun.add(co);
  out.push({ json: { ...j, dedupeKey: key } });
  if (out.length >= (cfg.maxPerRun || 8)) break;
}

// In dry runs, do NOT burn the dedupe key - you want the same list again while tuning.
if (!cfg.dryRun) { for (const o of out) sd.seen[o.json.dedupeKey] = now; }
return out;

const base = $('Loop Over Jobs').first().json;
const d = $input.first().json || {};
const desc = String(d.stellenangebotsBeschreibung || '');

const RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,24}/g;
const BLOCK = /(noreply|no-reply|donotreply|postmaster|example\.|@arbeitsagentur\.|\.png|\.jpg)/i;
const TLD = '(?:com|de|net|org|eu|io|ai|nl|at|ch|info|jobs|gmbh|group|tech)';

let email = '';
for (const raw of (desc.match(RE) || [])) {
  // Descriptions run words straight into the address, e.g. "jobs@firma.comBewerbende".
  let e = raw.replace(new RegExp('^([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+?\\.' + TLD + ')[A-Z\u00c4\u00d6\u00dc].*$'), '$1');
  e = e.replace(/[.,;:)\]]+$/, '').toLowerCase();
  if (BLOCK.test(e)) continue;
  email = e;
  break;
}

return [{ json: { ...base, description: desc.slice(0, 6000), contactEmail: email } }];

const cfg = $('Config').first().json;
const j = $input.first().json;
const desc = String(j.description || '');

// Write in the language the posting is written in; Dutch postings get English.
const germanish = /(wir suchen|deine aufgaben|ihre aufgaben|abgeschlossenes|kenntnisse|unbefristet|m\/w\/d|bewerbung)/i.test(desc);
const englishish = /(you will|your profile|we offer|responsibilities|requirements)/i.test(desc);
const lang = j.country === 'NL' ? 'English' : (germanish && !englishish ? 'German' : 'English');

const system = [
  'You write short, specific job application cover letters.',
  'Return STRICT JSON only: {"subject":"...","body":"...","fit":0,"reason":"..."}',
  'Write the subject and body in ' + lang + '.',
  'HARD RULE: never claim experience, tools or years that are absent from the CV. No invented metrics.',
  'body: 180-260 words, plain text, no markdown. Greeting, three short paragraphs, sign-off with the',
  'candidate name and phone number. Tie 2-3 concrete CV projects to requirements actually named in the posting.',
  'fit: an honest 0-100 match score. Be strict - score below 60 if core requirements are missing.',
  'reason: one sentence, in English, justifying the score.'
].join(' ');

const user = [
  'CANDIDATE CV:', cfg.cvText,
  '', 'CANDIDATE CONTACT: ' + cfg.myName + ', ' + cfg.myPhone + ', ' + cfg.myEmail,
  '', 'JOB POSTING:',
  'Title: ' + j.title,
  'Company: ' + j.company,
  'Location: ' + j.city + ', ' + j.country,
  'Link: ' + j.url,
  'Description:', desc.slice(0, 6000) || '(no description returned by the API)'
].join('\n');

return [{ json: { ...j, lang, llmPayload: {
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  temperature: 0.4,
  max_tokens: 1200,
  response_format: { type: 'json_object' }
}}}];

const cfg = $('Config').first().json;
const base = { ...$('Build Prompt').first().json };
delete base.llmPayload;

const res = $input.first().json || {};
let txt = '';
try { txt = res.choices[0].message.content || ''; } catch (e) { txt = ''; }

let p = {};
try { p = JSON.parse(txt); } catch (e) {
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) { try { p = JSON.parse(m[0]); } catch (e2) { p = {}; } }
}

const fit = Number.isFinite(Number(p.fit)) ? Number(p.fit) : 0;
const letter = String(p.body || '').trim();

return [{ json: { ...base,
  llmOk: letter.length > 80,
  llmError: letter.length > 80 ? '' : (res.error ? JSON.stringify(res.error).slice(0, 300) : 'no usable completion'),
  subject: String(p.subject || ('Application: ' + base.title)).slice(0, 180),
  letter,
  fit,
  reason: String(p.reason || ''),
  passesFit: fit >= (cfg.minFitScore || 70),
  hasEmail: !!base.contactEmail
}}];

const base = $('Parse Letter').first().json;
const inp = $input.first().json || {};
// The SMTP node returns accepted/messageId; the queue branch just passes the draft through.
const sent = !!(inp.messageId || (Array.isArray(inp.accepted) && inp.accepted.length));
return [{ json: { ...base, sent } }];

const cfg = $('Config').first().json;
const items = $input.all().map(i => i.json);
const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const sent = items.filter(i => i.sent);
const queued = items.filter(i => !i.sent).sort((a, b) => (b.fit || 0) - (a.fit || 0));

const card = (j, withLetter) => `
  <div style="border:1px solid #e2e2e2;border-radius:8px;padding:14px;margin:0 0 14px;">
    <div style="font-size:16px;font-weight:600;">${esc(j.title)}</div>
    <div style="color:#555;">${esc(j.company)} &middot; ${esc(j.city)}, ${esc(j.country)}
      &middot; fit <b>${esc(j.fit)}</b>${j.homeoffice ? ' &middot; remote/hybrid' : ''}</div>
    <div style="color:#777;font-size:13px;margin:4px 0;">${esc(j.reason)}</div>
    <div style="margin:6px 0;"><a href="${esc(j.url)}">Open posting &rarr;</a>
      ${j.contactEmail ? ' &middot; <a href="mailto:' + esc(j.contactEmail) + '">' + esc(j.contactEmail) + '</a>' : ''}</div>
    ${withLetter && j.letter ? '<details><summary style="cursor:pointer;color:#0b57d0;">Draft cover letter ('
      + esc(j.lang) + ')</summary><pre style="white-space:pre-wrap;font:13px/1.5 -apple-system,Segoe UI,sans-serif;'
      + 'background:#fafafa;padding:10px;border-radius:6px;">' + esc(j.letter) + '</pre></details>' : ''}
  </div>`;

const banner = cfg.dryRun
  ? '<div style="background:#fff4d6;border:1px solid #e8c766;padding:10px;border-radius:6px;margin-bottom:16px;">'
    + '<b>DRY RUN</b> - nothing was sent. Set <code>dryRun</code> to false in the Config node to arm it.</div>'
  : '';

const html = `<div style="font:14px/1.6 -apple-system,Segoe UI,Roboto,sans-serif;max-width:720px;margin:auto;color:#111;">
  <h2 style="margin:0 0 4px;">Job run - ${new Date().toISOString().slice(0, 10)}</h2>
  <p style="color:#666;margin:0 0 16px;">${items.length} new match(es) &middot; ${sent.length} applied &middot; ${queued.length} to review</p>
  ${banner}
  ${sent.length ? '<h3>Applied automatically</h3>' + sent.map(j => card(j, true)).join('') : ''}
  ${queued.length ? '<h3>Needs you (no contact email, low fit, or dry run)</h3>' + queued.map(j => card(j, true)).join('') : ''}
  <p style="color:#888;font-size:12px;">Sources: Bundesagentur fuer Arbeit (v6) &middot; Adzuna NL.</p>
</div>`;

return [{ json: {
  subject: `[Jobs] ${sent.length} applied, ${queued.length} to review - ${new Date().toISOString().slice(0, 10)}`,
  html
}}];
